def merge_intervals(intervals):
    """
    Merges overlapping closed integer intervals.
    Example: [[1, 3], [2, 4], [6, 8]] -> [[1, 4], [6, 8]]
    """
    if not intervals:
        return []

    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])

    merged = []
    for current in intervals:
        # If merged is empty or no overlap with the last interval in merged
        if not merged or current[0] > merged[-1][1]:
            merged.append(current)
        else:
            # There is an overlap, merge by updating the end of the last interval
            merged[-1][1] = max(merged[-1][1], current[1])

    return merged

if __name__ == "__main__":
    import pytest

    def test_merge_intervals():
        assert merge_intervals([[1, 3], [2, 6], [8, 10], [15, 18]]) == [[1,

